import { useState } from 'react';
import { JxTagInput, JxChip } from '@jinx-ui/react';

interface ArticleTagPickerProps {
  onChange?: (tags: string[]) => void;
}

export default function ArticleTagPicker({ onChange }: ArticleTagPickerProps) {
  const [tags, setTags] = useState<string[]>([]);

  const updateTags = (next: string[]) => {
    setTags(next);
    onChange?.(next);
  };

  const removeTag = (index: number) => {
    updateTags(tags.filter((_, i) => i !== index));
  };

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 'var(--jx-r-sm)' }}>
      <JxTagInput
        ariaLabel="Теги статьи"
        placeholder="Введите тег и нажмите Enter"
        value={tags}
        onValueChange={updateTags}
      />
      {tags.length > 0 && (
        <div style={{ display: 'flex', flexWrap: 'wrap', gap: 'var(--jx-r-sm)' }}>
          {tags.map((tag, index) => (
            <JxChip key={`${tag}-${index}`} removable onRemove={() => removeTag(index)}>
              {tag}
            </JxChip>
          ))}
        </div>
      )}
    </div>
  );
}

